function burn(x,y,s){EV.push(['b',ri(x),ri(y),s]);}
function shakeAt(x,y,a){EV.push(['k',ri(x),ri(y),a]);}
function smoke(x,y,n){EV.push(['m',ri(x),ri(y),n]);}
